# Firmware-only compact decoder variant; see build_usb_rx_compact.py.
# GENERATED by build_usb_rx.py. Packet experiment; NOT a USB device.
# TUSB1106: uio0=VP,1=VM,2=VPO,3=VMO,4=OE_n,5=SOFTCON.
# SPEED/SUSPND strapped low. No analog pads or protocol-aware RTL.
# param[0]=0 passive,1 emit diagnostic ACK after buffered validation.
# Event128..143; raw states144..249 then bytes144..154; state250..255.
SETO 56
SETOE 60
idle:
LDI r3, 0x22
PREAD r0, r3
JFAIL idle
LDI r1, 128
STORE r0, r1
PREAD r0, r3
ADDI r1, 1
STORE r0, r1
LDI r2, 14
record:
PREAD r0, r3
DJNZ r2, record
LDI r1, 130
LDI r0, 1
STORE r0, r1
ADDI r1, 1
LDI r2, 13
LDI r0, 0
clear_event:
STORE r0, r1
ADDI r1, 1
DJNZ r2, clear_event
LDI r3, 2
PREAD r0, r3
LDI r1, 132
STORE r0, r1
LDI r2, 0
LDI r3, 0
wait_idle:
IN r0
ANDI r0, 3
CMPI r0, 2
JFAIL idle_tick
JMP wait_sop
idle_tick:
DJNZ r3, wait_idle
DJNZ r2, wait_idle
JMP timeout
wait_sop:
IN r0
ANDI r0, 3
CMPI r0, 1
JFAIL sop_tick
LDI r1, 144
WAIT 10
sync_0:
IN r0
ANDI r0, 3
CMPI r0, 1
JFAIL form_error
WAIT 28
sync_1:
IN r0
ANDI r0, 3
CMPI r0, 2
JFAIL form_error
WAIT 28
sync_2:
IN r0
ANDI r0, 3
CMPI r0, 1
JFAIL form_error
WAIT 29
sync_3:
IN r0
ANDI r0, 3
CMPI r0, 2
JFAIL form_error
WAIT 28
sync_4:
IN r0
ANDI r0, 3
CMPI r0, 1
JFAIL form_error
WAIT 28
sync_5:
IN r0
ANDI r0, 3
CMPI r0, 2
JFAIL form_error
WAIT 29
sync_6:
IN r0
ANDI r0, 3
CMPI r0, 1
JFAIL form_error
WAIT 28
sync_7:
IN r0
ANDI r0, 3
CMPI r0, 1
JFAIL form_error
WAIT 27
JMP capture_0
sop_tick:
DJNZ r3, wait_sop
DJNZ r2, wait_sop
JMP timeout
capture_0:
IN r0
ANDI r0, 3
STORE r0, r1
ADDI r1, 1
JZ r0, eop_0
CMPI r1, 250
JFAIL room_0
JMP overflow
room_0:
WAIT 24
JMP capture_1
capture_1:
IN r0
ANDI r0, 3
STORE r0, r1
ADDI r1, 1
JZ r0, eop_1
CMPI r1, 250
JFAIL room_1
JMP overflow
room_1:
WAIT 23
JMP capture_2
capture_2:
IN r0
ANDI r0, 3
STORE r0, r1
ADDI r1, 1
JZ r0, eop_2
CMPI r1, 250
JFAIL room_2
JMP overflow
room_2:
WAIT 23
JMP capture_0
eop_0:
MOV r0, r1
ADDI r0, 255
LDI r1, 250
STORE r0, r1
WAIT 22
IN r0
ANDI r0, 3
CMPI r0, 0
JFAIL form_error
WAIT 28
IN r0
ANDI r0, 3
CMPI r0, 2
JFAIL form_error
JMP decode
eop_1:
MOV r0, r1
ADDI r0, 255
LDI r1, 250
STORE r0, r1
WAIT 21
IN r0
ANDI r0, 3
CMPI r0, 0
JFAIL form_error
WAIT 28
IN r0
ANDI r0, 3
CMPI r0, 2
JFAIL form_error
JMP decode
eop_2:
MOV r0, r1
ADDI r0, 255
LDI r1, 250
STORE r0, r1
WAIT 21
IN r0
ANDI r0, 3
CMPI r0, 0
JFAIL form_error
WAIT 29
IN r0
ANDI r0, 3
CMPI r0, 2
JFAIL form_error
JMP decode
decode:
LDI r1, 250
LOAD r0, r1
CMPI r0, 144
JFAIL decode_nonempty
JMP form_error
decode_nonempty:
LDI r0, 8
LDI r1, 251
STORE r0, r1
LDI r0, 144
LDI r1, 253
STORE r0, r1
ADDI r1, 1
STORE r0, r1
# r2=2*run_length+previous_VP; SYNC ends inK with run_length1.
LDI r2, 3
LDI r3, 0
raw_bit:
LDI r1, 254
LOAD r1, r1
LOAD r0, r1
CMPI r0, 3
JFAIL line_valid
JMP form_error
line_valid:
ANDI r0, 1
MOV r1, r2
XOR r1, r0
ANDI r1, 1
CMPI r1, 0
ANDI r2, 254
OR r2, r0
JFAIL decoded_zero
LDI r0, 1
JMP decoded_bit
decoded_zero:
LDI r0, 0
decoded_bit:
CMPLTI r2, 12
JFAIL must_stuff
JZ r0, zero_bit
ADDI r2, 2
JMP append_bit
zero_bit:
ANDI r2, 1
append_bit:
ROR r3
ANDI r3, 127
ROR r0
OR r3, r0
LDI r1, 251
LOAD r0, r1
ADDI r0, 255
STORE r0, r1
JZ r0, byte_full
JMP next_raw
must_stuff:
JZ r0, stuff_ok
JMP stuff_error
stuff_ok:
ANDI r2, 1
JMP next_raw
byte_full:
LDI r1, 253
LOAD r1, r1
STORE r3, r1
ADDI r1, 1
MOV r0, r1
LDI r1, 253
STORE r0, r1
LDI r1, 251
LDI r0, 8
STORE r0, r1
next_raw:
LDI r1, 254
LOAD r0, r1
ADDI r0, 1
STORE r0, r1
LDI r1, 250
LOAD r1, r1
XOR r0, r1
JZ r0, packet_end
JMP raw_bit
packet_end:
CMPLTI r2, 12
JFAIL stuff_error
JMP aligned
aligned:
LDI r1, 251
LOAD r0, r1
CMPI r0, 8
JFAIL form_error
LDI r1, 253
LOAD r0, r1
CMPLTI r0, 147
JFAIL length_high
JMP form_error
length_high:
CMPLTI r0, 156
JFAIL overflow
# Complementary PID halves, then DATA0 or DATA1 only in this probe.
LDI r1, 144
LOAD r0, r1
MOV r2, r0
SHR r0
SHR r0
SHR r0
SHR r0
XOR r0, r2
ANDI r0, 15
CMPI r0, 15
JFAIL pid_error
CMPI r2, 0xc3
JFAIL maybe_data1
JMP crc_begin
maybe_data1:
CMPI r2, 0x4b
JFAIL unsupported
crc_begin:
LDI r2, 255
LDI r3, 255
LDI r0, 145
LDI r1, 254
STORE r0, r1
crc_byte:
LDI r1, 254
LOAD r1, r1
LOAD r0, r1
XOR r2, r0
LDI r0, 8
LDI r1, 251
STORE r0, r1
crc_bit:
MOV r0, r2
ANDI r0, 1
ROR r3
MOV r1, r3
ANDI r1, 128
ANDI r3, 127
SHR r2
OR r2, r1
JZ r0, crc_no_xor
XORI r2, 1
XORI r3, 160
crc_no_xor:
LDI r1, 251
LOAD r0, r1
ADDI r0, 255
STORE r0, r1
JZ r0, crc_next
JMP crc_bit
crc_next:
LDI r1, 254
LOAD r0, r1
ADDI r0, 1
STORE r0, r1
LDI r1, 253
LOAD r1, r1
XOR r0, r1
JZ r0, crc_done
JMP crc_byte
crc_done:
CMPI r2, 1
JFAIL crc_error
CMPI r3, 0xb0
JFAIL crc_error
# Optional diagnostic ACK: measure this path, do not claim timely USB.
LDI r1, 0
LOAD r0, r1
JZ r0, output
SETO 36
WAIT 31
SETO 40
WAIT 31
SETO 36
WAIT 32
SETO 40
WAIT 31
SETO 36
WAIT 31
SETO 40
WAIT 32
SETO 36
WAIT 31
SETO 36
WAIT 31
SETO 40
WAIT 32
SETO 40
WAIT 31
SETO 36
WAIT 31
SETO 40
WAIT 32
SETO 40
WAIT 31
SETO 36
WAIT 31
SETO 36
WAIT 32
SETO 36
WAIT 31
SETO 32
WAIT 31
SETO 32
WAIT 32
SETO 40
WAIT 31
SETO 56
output:
LDI r1, 253
LOAD r2, r1
ADDI r2, 112
MOV r0, r2
LDI r1, 134
STORE r0, r1
LDI r1, 144
output_byte:
LOAD r0, r1
LDI r3, 0x30
PWRITE r0, r3
LDI r0, 0
ADDI r3, 1
PWRITE r0, r3
ADDI r3, 1
PWRITE r0, r3
ADDI r1, 1
DJNZ r2, output_byte
JMP publish
timeout:
LDI r2, 6
JMP failure
crc_error:
LDI r2, 16
JMP failure
form_error:
LDI r2, 17
JMP failure
unsupported:
LDI r2, 18
JMP failure
stuff_error:
LDI r2, 19
JMP failure
overflow:
LDI r2, 20
JMP failure
pid_error:
LDI r2, 21
failure:
SETO 56
LDI r1, 131
STORE r2, r1
publish:
# Output metadata defaults0; no per-byte nonzero metadata used here.
LDI r1, 128
LDI r2, 16
LDI r3, 0x40
event:
LOAD r0, r1
PWRITE r0, r3
ADDI r1, 1
DJNZ r2, event
LDI r0, 0
ADDI r3, 1
PWRITE r0, r3
JMP idle
